jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };

  // ─── Audience gate ────────────────────────────────────────────────
  // Defensive in-tool check; the tool_configs audienceEmails gate is
  // the primary filter but this prevents accidental wide-load damage.
  var ALLOWED = { "andrew_nemiroff@colpal.com": 1 };
  var ident = (eli.tools && typeof eli.tools.userIdentity === "function")
    ? eli.tools.userIdentity() : {};
  var userEmail = String((ident && ident.email) || "").toLowerCase().trim();
  if (!ALLOWED[userEmail]) {
    eli.log.event("tool", "eli_agent_skip", { reason: "not_allowed", email: userEmail });
    return;
  }

  // ─── Agent registry ───────────────────────────────────────────────
  // V1 ships with one agent (apply_instruction → "Revise Document").
  // Adding agent #2 = push another entry; the dropdown + Manage Agents
  // modal are data-driven off this list. displayName is what the user
  // sees; id is what flows through dispatch payloads + IDB keys.
  var AGENT_REGISTRY = [
    {
      id: "apply_instruction",
      displayName: "Revise Document",
      icon: "🤖",
      description: "Make multiple edits across the doc based on a free-form instruction (e.g., \"Make this Colgate-friendly\", \"Shorten by 30%\").",
      defaultSettings: {
        tone: "balanced",  // conservative | balanced | aggressive
        scope: ["payment-terms", "indemnity", "termination", "ip", "mfn", "audit", "warranty"],
      },
    },
  ];

  // ─── Per-user agent settings (IDB) ────────────────────────────────
  // One row per agent id under config store. Settings ride on the
  // agent_settings shape: { enabled, tone, scope }. Defaults derive
  // from the registry's defaultSettings until the user overrides.
  var SETTINGS_KEY_PREFIX = "eli_agent_settings_";
  function _settingsKey(agentId) { return SETTINGS_KEY_PREFIX + agentId; }
  function _getAgentSettings(agentId) {
    var entry = _findAgent(agentId);
    if (!entry) return Promise.resolve(null);
    return eli.storage.get("config", _settingsKey(agentId)).then(function (row) {
      var saved = (row && row.settings) || {};
      return Object.assign(
        { enabled: true },
        entry.defaultSettings || {},
        saved
      );
    }).catch(function () {
      return Object.assign({ enabled: true }, entry.defaultSettings || {});
    });
  }
  function _setAgentSettings(agentId, settings) {
    if (!_findAgent(agentId)) return Promise.reject(new Error("Unknown agent id: " + agentId));
    return eli.storage.put("config", {
      key: _settingsKey(agentId),
      agentId: agentId,
      settings: settings || {},
      updatedAt: new Date().toISOString(),
    });
  }
  function _findAgent(id) {
    for (var i = 0; i < AGENT_REGISTRY.length; i++) {
      if (AGENT_REGISTRY[i].id === id) return AGENT_REGISTRY[i];
    }
    return null;
  }
  // Returns the public registry projection — what callers see via
  // list_agents dispatch. Strips internal fields, joins persisted
  // enable state per row. Async because settings live in IDB.
  function _listAgents() {
    return Promise.all(AGENT_REGISTRY.map(function (a) {
      return _getAgentSettings(a.id).then(function (s) {
        return {
          id: a.id,
          displayName: a.displayName,
          icon: a.icon,
          description: a.description,
          enabled: s.enabled !== false,
        };
      });
    }));
  }

  // ─── Active mode state ────────────────────────────────────────────
  // _currentMode: "ask_eli" (default Q&A) OR "agent:<agentId>".
  // Used by intercept_submit to decide whether to take over a Send
  // click in ask_eli, and by the dropdown UI to show the active row.
  // Resets to "ask_eli" on overlay close (per Phase 1 spec).
  var _currentMode = "ask_eli";
  function _setMode(mode) {
    _currentMode = mode;
    _onModeChange(mode);
  }
  function _onModeChange(mode) {
    // Tint the caret + ask_eli title so the user sees at a glance
    // when an agent mode is active (vs default Q&A). No label
    // changes — title stays "Ask ELI" per the user-facing design.
    document.querySelectorAll("[data-eli-agent-dropdown-trigger]").forEach(function (caret) {
      if (mode === "ask_eli") caret.classList.remove("_eg_caret_active");
      else caret.classList.add("_eg_caret_active");
      // Tooltip reflects current mode for quick verification.
      var label = _currentDropdownLabel(mode);
      caret.title = "Mode: " + label.icon + " " + label.text + " — click to switch";
    });
  }
  function _currentDropdownLabel(mode) {
    if (mode === "ask_eli") return { icon: "💬", text: "Ask Eli" };
    var agentId = mode.replace(/^agent:/, "");
    var a = _findAgent(agentId);
    return a ? { icon: a.icon, text: a.displayName } : { icon: "💬", text: "Ask Eli" };
  }

  // ─── Dropdown painter — listens for ask_eli's mount event ─────────
  // ask_eli emits 'ask_eli:input_mounted' after rendering its chat
  // input bar with { slotEl, sendBtn, inputEl, getQaContext }. We
  // paint the dropdown into slotEl, mark the send button so we can
  // flip its label on mode change, and rely on intercept_submit
  // (registered below) to take over when an agent mode is active.
  function _paintDropdown(payload) {
    var slot = payload && payload.slotEl;
    var sendBtn = payload && payload.sendBtn;
    if (!slot) return;
    if (sendBtn) sendBtn.setAttribute("data-eli-agent-send-btn", "1");

    // Just a clickable caret next to the title — NO button chrome.
    // Reads as "the title has a dropdown affordance," not "there is
    // a separate button you might mistake for an action." When an
    // agent mode is active, the caret tints amber to signal state
    // without changing the title text.
    slot.innerHTML =
      '<span class="_eg_caret_inline" data-eli-agent-dropdown-trigger="1" ' +
      'title="Switch mode (Ask Eli vs an agent)">▾</span>';

    var trigger = slot.querySelector('[data-eli-agent-dropdown-trigger="1"]');
    if (trigger) trigger.onclick = function (ev) {
      ev.preventDefault();
      ev.stopPropagation();
      _openDropdownMenu(trigger);
    };

    // Sync initial state (caret color) in case mode was set before mount.
    _onModeChange(_currentMode);
  }

  // Opens the floating menu anchored to the trigger button. List is
  // built fresh each open (so a Manage-Agents enable/disable change
  // takes effect without a full re-paint).
  function _openDropdownMenu(triggerEl) {
    _closeDropdownMenu();
    _listAgents().then(function (agents) {
      var rect = triggerEl.getBoundingClientRect();
      var menu = document.createElement("div");
      menu.id = "_eg_dropdown_menu";
      menu.style.cssText =
        "position:fixed;top:" + (rect.bottom + 4) + "px;left:" + rect.left + "px;" +
        "z-index:99999;background:#fff;border:1px solid #cbd5e1;" +
        "box-shadow:0 8px 24px rgba(15,23,42,0.18);min-width:240px;" +
        "font-family:Inter,'Segoe UI',system-ui,sans-serif;font-size:12px;";
      var rows = '';
      // Always-present Ask Eli row.
      rows += _menuRowHtml({ value: "ask_eli", icon: "💬", label: "Ask Eli", isActive: _currentMode === "ask_eli" });
      // Divider then enabled agents.
      var enabled = agents.filter(function (a) { return a.enabled; });
      if (enabled.length) rows += '<div class="_eg_menu_divider"></div>';
      enabled.forEach(function (a) {
        rows += _menuRowHtml({
          value: "agent:" + a.id, icon: a.icon, label: a.displayName,
          isActive: _currentMode === ("agent:" + a.id),
        });
      });
      // Footer — always-present Manage Agents action.
      rows += '<div class="_eg_menu_divider"></div>';
      rows += _menuRowHtml({ value: "__manage", icon: "⚙", label: "Manage Agents…", isActive: false, isAction: true });
      menu.innerHTML = rows;
      document.body.appendChild(menu);

      menu.querySelectorAll("[data-eg-menu-row]").forEach(function (row) {
        row.onclick = function () {
          var value = row.getAttribute("data-eg-menu-row");
          _closeDropdownMenu();
          if (value === "__manage") { _openManageAgentsModal(); return; }
          _setMode(value);
        };
      });
      // Outside-click closes menu.
      setTimeout(function () {
        document.addEventListener("mousedown", _outsideMenuClick, true);
      }, 0);
    });
  }
  function _menuRowHtml(opts) {
    var bg = opts.isActive ? "background:#dbeafe;color:#1e3a8a;" : "background:#fff;color:#0f172a;";
    return '<div data-eg-menu-row="' + _esc(opts.value) + '" class="_eg_menu_row' + (opts.isAction ? ' _eg_menu_row_action' : '') + '" ' +
      'style="display:flex;align-items:center;gap:8px;padding:8px 12px;cursor:pointer;' + bg + '">' +
        '<span style="font-size:13px;width:18px;text-align:center;">' + _esc(opts.icon) + '</span>' +
        '<span style="font-weight:' + (opts.isActive ? '700' : '500') + ';">' + _esc(opts.label) + '</span>' +
      '</div>';
  }
  function _closeDropdownMenu() {
    var existing = document.getElementById("_eg_dropdown_menu");
    if (existing && existing.parentNode) existing.parentNode.removeChild(existing);
    document.removeEventListener("mousedown", _outsideMenuClick, true);
  }
  function _outsideMenuClick(ev) {
    var menu = document.getElementById("_eg_dropdown_menu");
    if (!menu) return;
    if (menu.contains(ev.target)) return;
    // Don't close if the user clicked the trigger again — that's a
    // toggle which the trigger's own handler will manage.
    var trig = ev.target.closest && ev.target.closest("[data-eli-agent-dropdown-trigger]");
    if (trig) return;
    _closeDropdownMenu();
  }

  // ─── Agent overlay — status-driven body, auto-kicks plan ─────────
  // States: capturing | planning | review | applying | applied | error
  // Header stays constant; body re-renders per status. Plan kicks
  // off automatically on overlay open (user already typed +
  // submitted in ask_eli, no need to ask twice). Cancel during
  // planning aborts the in-flight AI call.
  function _openAgentOverlay(payload) {
    _closeAgentOverlay();
    var agentId = payload && payload.agent;
    var instruction = (payload && payload.instruction) || "";
    var agent = _findAgent(agentId);
    if (!agent) {
      eli.log.event("tool", "eli_agent_open_unknown", { agent: agentId });
      return;
    }

    _egActive = {
      agent: agentId,
      instruction: instruction,
      qaIndex: (payload && payload.qaIndex) || null,
      docHash: (payload && payload.docHash) || null,
      plan: null,
      acceptance: {},        // editId → "accepted"|"rejected"|"pending"
      editOverrides: {},     // editId → {replacementText: "user-edit"}
      status: "capturing",
      error: null,
      applyResult: null,     // {applied, failures} after apply
      cancelToken: null,     // eli.cancel.token() during planning
      openedAt: new Date().toISOString(),
    };

    var ov = document.createElement("div");
    ov.id = "_eli_agent_overlay";
    ov.className = "_eg_overlay";
    ov.innerHTML =
      '<div id="_eg_header" class="_eg_header">' +
        '<div class="_eg_header_title">' +
          '<span class="_eg_header_icon">' + _esc(agent.icon) + '</span>' +
          '<span class="_eg_header_label">' + _esc(agent.displayName) + '</span>' +
        '</div>' +
        '<div class="_eg_header_actions">' +
          '<button id="_eg_close" type="button" class="_eg_btn_ghost" title="Close">✕</button>' +
        '</div>' +
      '</div>' +
      '<div id="_eg_body" class="_eg_body"></div>';
    document.body.appendChild(ov);

    var headerEl = document.getElementById("_eg_header");
    if (typeof window._eliMakeDraggable === "function" && headerEl) {
      try { window._eliMakeDraggable(ov, headerEl); } catch (_) {}
    }
    if (typeof window._eliMakeResizable === "function") {
      try { window._eliMakeResizable(ov); } catch (_) {}
    }
    document.getElementById("_eg_close").onclick = _closeAgentOverlay;

    eli.log.event("tool", "eli_agent_overlay_opened", {
      agent: agentId,
      instructionLen: (instruction || "").length,
    });

    // Render initial body + auto-kick the plan.
    _renderOverlayBody();
    _runPlan();
  }
  function _closeAgentOverlay() {
    // Cancel any in-flight planning so the AI call doesn't keep
    // burning tokens after the user closed the panel.
    if (_egActive && _egActive.cancelToken && typeof _egActive.cancelToken.abort === "function") {
      try { _egActive.cancelToken.abort(); } catch (_) {}
    }
    var ov = document.getElementById("_eli_agent_overlay");
    if (ov && ov.parentNode) ov.parentNode.removeChild(ov);
    if (_currentMode !== "ask_eli") _setMode("ask_eli");
    // Keep _egActive intact across close → reopen could resume in V2.
    // For V1 each new instruction submit overwrites it via _openAgentOverlay.
  }
  // Active-session container.
  var _egActive = null;

  // Repaint just the body — header stays, status-driven dispatch.
  function _renderOverlayBody() {
    var body = document.getElementById("_eg_body");
    if (!body || !_egActive) return;
    switch (_egActive.status) {
      case "capturing": body.innerHTML = _bodyCapturing(); _wireCapturingControls(body); break;
      case "planning":  body.innerHTML = _bodyPlanning();  _wirePlanningControls(body);  break;
      case "review":    body.innerHTML = _bodyReview();    _wireReviewControls(body);    break;
      case "applying":  body.innerHTML = _bodyApplying();  break;
      case "applied":   body.innerHTML = _bodyApplied();   _wireAppliedControls(body);   break;
      case "error":     body.innerHTML = _bodyError();     _wireErrorControls(body);     break;
      default:          body.innerHTML = _bodyCapturing();
    }
  }
  function _bodyHeader() {
    return '' +
      '<div class="_eg_section_label">INSTRUCTION</div>' +
      '<div class="_eg_instruction">' + _esc(_egActive.instruction || "(no instruction)") + '</div>';
  }
  function _bodyCapturing() {
    return _bodyHeader() +
      '<div class="_eg_status_box">' +
        '<div class="_eg_status_dot"></div>' +
        '<div>Reading the document…</div>' +
      '</div>';
  }
  function _wireCapturingControls() { /* nothing interactive */ }
  function _bodyPlanning() {
    var paraCount = (_egActive.qaIndex && _egActive.qaIndex.length) || 0;
    return _bodyHeader() +
      '<div class="_eg_status_box">' +
        '<div class="_eg_status_dot"></div>' +
        '<div>Planning edits across ' + paraCount + ' paragraph' + (paraCount === 1 ? "" : "s") + '… <em>(this can take ~10–20s)</em></div>' +
      '</div>' +
      '<div class="_eg_actions_row">' +
        '<button id="_eg_cancel_plan" type="button" class="_eg_btn_secondary">Cancel</button>' +
      '</div>';
  }
  function _wirePlanningControls(body) {
    var btn = body.querySelector("#_eg_cancel_plan");
    if (btn) btn.onclick = function () {
      if (_egActive && _egActive.cancelToken && typeof _egActive.cancelToken.abort === "function") {
        try { _egActive.cancelToken.abort(); } catch (_) {}
      }
      _egActive.status = "error";
      _egActive.error = "Cancelled.";
      _renderOverlayBody();
    };
  }
  function _bodyError() {
    return _bodyHeader() +
      '<div class="_eg_error_box">' +
        '<div class="_eg_error_title">Couldn\'t generate plan</div>' +
        '<div class="_eg_error_msg">' + _esc(_egActive.error || "Unknown error") + '</div>' +
      '</div>' +
      '<div class="_eg_actions_row">' +
        '<button id="_eg_retry" type="button" class="_eg_btn_primary">Retry</button>' +
      '</div>';
  }
  function _wireErrorControls(body) {
    var btn = body.querySelector("#_eg_retry");
    if (btn) btn.onclick = function () {
      _egActive.status = "capturing";
      _egActive.error = null;
      _renderOverlayBody();
      _runPlan();
    };
  }
  function _bodyApplying() {
    return _bodyHeader() +
      '<div class="_eg_status_box">' +
        '<div class="_eg_status_dot"></div>' +
        '<div>Applying redlines to the document…</div>' +
      '</div>';
  }
  function _bodyApplied() {
    var r = _egActive.applyResult || { applied: 0, failures: [] };
    var failHtml = "";
    if (r.failures && r.failures.length) {
      failHtml = '<div class="_eg_section_label" style="margin-top:14px;">COULDN\'T ANCHOR (' + r.failures.length + ')</div>' +
        r.failures.map(function (f) {
          return '<div class="_eg_fail_card">' +
            '<div class="_eg_fail_reason">' + _esc(f.reason || "anchor not found") + '</div>' +
            '<div class="_eg_fail_text">' + _esc((f.edit && (f.edit.anchorText || f.edit.replacementText)) || "") + '</div>' +
          '</div>';
        }).join("");
    }
    return _bodyHeader() +
      '<div class="_eg_applied_box">' +
        '<div class="_eg_applied_title">✓ Applied ' + r.applied + ' redline' + (r.applied === 1 ? "" : "s") + ' to the document.</div>' +
        '<div class="_eg_applied_sub">Word now shows them as tracked changes — accept/reject in the Review pane.</div>' +
      '</div>' +
      failHtml +
      '<div class="_eg_actions_row">' +
        '<button id="_eg_new_plan" type="button" class="_eg_btn_secondary">New Plan</button>' +
        '<button id="_eg_close_done" type="button" class="_eg_btn_primary">Done</button>' +
      '</div>';
  }
  function _wireAppliedControls(body) {
    var nb = body.querySelector("#_eg_new_plan");
    if (nb) nb.onclick = function () {
      _egActive.plan = null;
      _egActive.acceptance = {};
      _egActive.editOverrides = {};
      _egActive.applyResult = null;
      _egActive.status = "capturing";
      _renderOverlayBody();
      _runPlan();
    };
    var cb = body.querySelector("#_eg_close_done");
    if (cb) cb.onclick = _closeAgentOverlay;
  }

  // ─── Review body — cards grouped by section ───────────────────────
  function _bodyReview() {
    var plan = _egActive.plan || { summary: "", edits: [] };
    var edits = plan.edits || [];
    if (!edits.length) {
      return _bodyHeader() +
        '<div class="_eg_empty_box">' +
          '<div class="_eg_empty_title">No edits proposed</div>' +
          '<div class="_eg_empty_msg">' + _esc(plan.summary || "I read the doc but didn't find anything to change for this brief. Try rephrasing or being more specific.") + '</div>' +
        '</div>' +
        '<div class="_eg_actions_row">' +
          '<button id="_eg_replan" type="button" class="_eg_btn_secondary">Try again</button>' +
        '</div>';
    }
    // Group edits by section (or category if no section).
    var groups = {};
    var groupOrder = [];
    edits.forEach(function (e) {
      var key = e.section || e.category || "Other";
      if (!groups[key]) { groups[key] = []; groupOrder.push(key); }
      groups[key].push(e);
    });
    var summary = plan.summary || "";
    var counts = _editCounts();
    var cardsHtml = groupOrder.map(function (g) {
      return '<div class="_eg_group">' +
        '<div class="_eg_group_header">' + _esc(g) + ' <span class="_eg_group_count">(' + groups[g].length + ')</span></div>' +
        groups[g].map(function (e) { return _editCardHtml(e); }).join("") +
      '</div>';
    }).join("");
    return _bodyHeader() +
      '<div class="_eg_summary">' + _esc(summary) + '</div>' +
      '<div class="_eg_review_stats">' +
        '<span class="_eg_stat _eg_stat_total">' + counts.total + ' edits</span>' +
        '<span class="_eg_stat _eg_stat_accepted">' + counts.accepted + ' accepted</span>' +
        '<span class="_eg_stat _eg_stat_pending">' + counts.pending + ' pending</span>' +
        (counts.rejected ? '<span class="_eg_stat _eg_stat_rejected">' + counts.rejected + ' rejected</span>' : '') +
      '</div>' +
      cardsHtml +
      '<div class="_eg_actions_row _eg_actions_sticky">' +
        '<button id="_eg_accept_all_high" type="button" class="_eg_btn_secondary">Accept All ●●●●○+</button>' +
        '<button id="_eg_accept_all" type="button" class="_eg_btn_secondary">Accept All</button>' +
        '<button id="_eg_apply" type="button" class="_eg_btn_primary _eg_btn_apply" ' + (counts.accepted ? '' : 'disabled') + '>' +
          'Apply ' + counts.accepted + ' to Doc' +
        '</button>' +
      '</div>';
  }
  function _editCounts() {
    var edits = (_egActive.plan && _egActive.plan.edits) || [];
    var c = { total: edits.length, accepted: 0, rejected: 0, pending: 0 };
    edits.forEach(function (e) {
      var s = _egActive.acceptance[e.id] || "pending";
      if (s === "accepted") c.accepted++;
      else if (s === "rejected") c.rejected++;
      else c.pending++;
    });
    return c;
  }
  function _editCardHtml(e) {
    var status = _egActive.acceptance[e.id] || "pending";
    var statusCls = "_eg_card_" + status;
    var reviewCls = e.requiresHumanReview ? " _eg_card_review" : "";
    var dots = _confidenceDots(e.confidence);
    var typeBadge = '<span class="_eg_type_badge _eg_type_' + (e.type || "replace") + '">' + _esc((e.type || "replace").toUpperCase()) + '</span>';
    var diffHtml = _renderDiff(e);
    return '<div class="_eg_card ' + statusCls + reviewCls + '" data-eg-edit-id="' + _esc(e.id) + '">' +
      '<div class="_eg_card_top">' +
        '<div class="_eg_card_meta">' +
          typeBadge +
          (e.section ? '<span class="_eg_card_section">' + _esc(e.section) + '</span>' : '') +
          '<span class="_eg_card_dots" title="Confidence: ' + (e.confidence || 3) + '/5">' + dots + '</span>' +
        '</div>' +
        (e.requiresHumanReview ? '<span class="_eg_card_review_pill">⚠ needs review</span>' : '') +
      '</div>' +
      '<div class="_eg_card_diff">' + diffHtml + '</div>' +
      '<div class="_eg_card_rationale">' + _esc(e.rationale || "") + '</div>' +
      '<div class="_eg_card_actions">' +
        '<button type="button" class="_eg_card_btn _eg_card_accept" data-eg-action="accept" data-eg-edit-id="' + _esc(e.id) + '"' + (status === "accepted" ? ' disabled' : '') + '>✓ Accept</button>' +
        '<button type="button" class="_eg_card_btn _eg_card_reject" data-eg-action="reject" data-eg-edit-id="' + _esc(e.id) + '"' + (status === "rejected" ? ' disabled' : '') + '>✗ Reject</button>' +
        (status !== "pending" ? '<button type="button" class="_eg_card_btn _eg_card_undo" data-eg-action="undo" data-eg-edit-id="' + _esc(e.id) + '">↺ Undo</button>' : '') +
      '</div>' +
    '</div>';
  }
  function _confidenceDots(n) {
    n = Math.max(1, Math.min(5, n || 3));
    var s = "";
    for (var i = 1; i <= 5; i++) s += (i <= n ? '●' : '○');
    return s;
  }
  function _renderDiff(e) {
    var t = e.type || "replace";
    if (t === "delete") {
      return '<div class="_eg_diff_orig"><del>' + _esc(e.anchorText || "") + '</del></div>';
    }
    if (t === "insert") {
      return '<div class="_eg_diff_orig _eg_diff_insert_anchor">After: <em>' + _esc(_truncate(e.anchorText, 80)) + '</em></div>' +
        '<div class="_eg_diff_new"><ins>' + _esc(e.replacementText || "") + '</ins></div>';
    }
    // replace
    return '<div class="_eg_diff_orig"><del>' + _esc(e.anchorText || "") + '</del></div>' +
      '<div class="_eg_diff_new"><ins>' + _esc(e.replacementText || "") + '</ins></div>';
  }
  function _truncate(s, n) {
    s = String(s || "");
    return s.length <= n ? s : s.slice(0, n) + "…";
  }
  function _wireReviewControls(body) {
    body.querySelectorAll("[data-eg-action]").forEach(function (btn) {
      btn.onclick = function () {
        var action = btn.getAttribute("data-eg-action");
        var id = btn.getAttribute("data-eg-edit-id");
        if (action === "accept") _egActive.acceptance[id] = "accepted";
        else if (action === "reject") _egActive.acceptance[id] = "rejected";
        else if (action === "undo") _egActive.acceptance[id] = "pending";
        _renderOverlayBody();
      };
    });
    var ah = body.querySelector("#_eg_accept_all_high");
    if (ah) ah.onclick = function () {
      (_egActive.plan.edits || []).forEach(function (e) {
        if ((e.confidence || 0) >= 4 && !e.requiresHumanReview &&
            _egActive.acceptance[e.id] !== "rejected") {
          _egActive.acceptance[e.id] = "accepted";
        }
      });
      _renderOverlayBody();
    };
    var aa = body.querySelector("#_eg_accept_all");
    if (aa) aa.onclick = function () {
      (_egActive.plan.edits || []).forEach(function (e) {
        if (_egActive.acceptance[e.id] !== "rejected") {
          _egActive.acceptance[e.id] = "accepted";
        }
      });
      _renderOverlayBody();
    };
    var ap = body.querySelector("#_eg_apply");
    if (ap) ap.onclick = _applyAcceptedEdits;
    var rp = body.querySelector("#_eg_replan");
    if (rp) rp.onclick = function () {
      _egActive.plan = null;
      _egActive.status = "capturing";
      _renderOverlayBody();
      _runPlan();
    };
  }

  // ─── Plan pipeline ────────────────────────────────────────────────
  // Three async steps: ensure QA index → call AI with schema → store.
  function _runPlan() {
    if (!_egActive) return Promise.resolve();
    _egActive.status = "capturing";
    _renderOverlayBody();
    return _ensureQaIndex().then(function (idx) {
      if (!_egActive) return; // closed mid-flight
      _egActive.qaIndex = idx.qaIndex || [];
      _egActive.docHash = idx.docHash || null;
      _egActive.indexSource = idx.source || "unknown";
      if (!_egActive.qaIndex.length) {
        throw new Error(idx.source === "fallback_failed"
          ? "Couldn't read the document — check that it's open and try again."
          : "Document appears empty — add some content and try again.");
      }
      _egActive.status = "planning";
      _renderOverlayBody();
      // Fetch agent's persisted settings (tone, scope) so the prompt
      // can reflect the user's per-agent preferences. Defaults if
      // nothing saved yet.
      return _getAgentSettings(_egActive.agent).then(function (settings) {
        var prompt = _buildPlanPromptSync(_egActive, settings);
        _egActive.cancelToken = (eli.cancel && typeof eli.cancel.token === "function")
          ? eli.cancel.token() : null;
        var opts = { sanitize: false };
        if (_egActive.cancelToken && _egActive.cancelToken.signal) {
          opts.signal = _egActive.cancelToken.signal;
        }
        return eli.ai.completeJSON(prompt, PLAN_SCHEMA, opts);
      });
    }).then(function (plan) {
      if (!_egActive) return;
      var validated = _validatePlan(plan);
      _egActive.plan = validated;
      _egActive.acceptance = {};
      validated.edits.forEach(function (e) { _egActive.acceptance[e.id] = "pending"; });
      _egActive.status = "review";
      _egActive.cancelToken = null;
      _renderOverlayBody();
      eli.log.event("tool", "eli_agent_plan_ready", {
        agent: _egActive.agent,
        editCount: validated.edits.length,
        instructionLen: (_egActive.instruction || "").length,
      });
    }).catch(function (err) {
      if (!_egActive) return;
      _egActive.status = "error";
      _egActive.error = (err && err.message) || String(err);
      _egActive.cancelToken = null;
      _renderOverlayBody();
      eli.log.event("tool", "eli_agent_plan_failed", { msg: _egActive.error });
    });
  }
  function _ensureQaIndex() {
    // Two-tier strategy.
    //   Tier A: ask_eli's cached QA index — has paragraph bookmarks
    //   (ELI_QA_*) + section labels. Best for bookmark-precise anchor
    //   apply. Available only after ask_eli has warmed the index for
    //   this doc (happens on its open or on first question).
    //   Tier B: build a minimal index ourselves via direct Word.js
    //   read. No bookmarks, no sections — just text + synthetic ids.
    //   Apply still works via body-wide searchWithFallback fallback.
    // Always prefer A when available. Fall through to B otherwise.
    try {
      var result = eli.dispatch("ask_eli", "get_qa_index");
      if (result && Array.isArray(result.qaIndex) && result.qaIndex.length) {
        return Promise.resolve({
          qaIndex: result.qaIndex,
          docHash: result.docHash,
          source: "ask_eli",
        });
      }
    } catch (_) {}
    return _buildSimpleIndex();
  }
  // Fallback index — read body paragraphs directly. Skips empty paras
  // and very-short noise (page numbers, single chars) so the prompt
  // stays focused on substantive content. Synthetic ids "_eg_p_<n>"
  // — apply path falls back to body-wide search since these aren't
  // real Word bookmarks.
  function _buildSimpleIndex() {
    if (!eli.host || typeof eli.host.runRaw !== "function") {
      return Promise.resolve({ qaIndex: [], docHash: null, source: "fallback_unavailable" });
    }
    return eli.host.runRaw("eli_agent:fallback_index", function (context) {
      var paragraphs = context.document.body.paragraphs;
      paragraphs.load("text");
      return context.sync().then(function () {
        var items = paragraphs.items || [];
        var index = [];
        for (var i = 0; i < items.length; i++) {
          var t = String(items[i].text || "").trim();
          if (t.length < 3) continue;  // skip page-number / noise paragraphs
          index.push({
            id: "_eg_p_" + i,
            text: t.length > 1500 ? t.slice(0, 1500) + "…" : t,
            section: null,
          });
        }
        return { qaIndex: index, docHash: null, source: "fallback" };
      });
    }).catch(function (err) {
      eli.log.event("tool", "eli_agent_fallback_index_failed", { msg: err && err.message });
      return { qaIndex: [], docHash: null, source: "fallback_failed" };
    });
  }

  // ─── Plan prompt + schema ─────────────────────────────────────────
  // Sync builder — _runPlan resolves settings first, then calls this.
  function _buildPlanPromptSync(active, settings) {
    var docPayload = JSON.stringify(active.qaIndex, null, 1);
    var tone = (settings && settings.tone) || "balanced";
    var toneGuide =
      tone === "aggressive"   ? "Take a strong position in favor of the requestor's interests. Push for materially better terms across all in-scope categories." :
      tone === "conservative" ? "Make modest, market-standard adjustments only. Avoid edits that would likely be rejected as unreasonable." :
                                "Balanced — propose edits that improve the requestor's position with terms a sophisticated counterparty would likely accept.";
    return [
      "You are an associate attorney revising a contract per the client's instruction.",
      "Return a JSON object that conforms EXACTLY to the schema. No prose, no preamble.",
      "",
      "RULES:",
      "1. Anchor by VERBATIM TEXT QUOTE in `anchorText` (case + punctuation insensitive matching is OK).",
      "2. `paragraphId` MUST match the `id` field of one of the paragraphs in the document below (e.g., 'ELI_QA_14').",
      "3. `section` should reference the document's section/article (e.g., '§4.2 Payment Terms') from the paragraph's `section` field.",
      "4. Prefer MINIMAL edits — change only the words that need to change.",
      "5. For judgment-heavy spots (mutual indemnity, asymmetric obligations, scope changes), set `requiresHumanReview: true`.",
      "6. Confidence (1-5): 5 = standard market move, 4 = reasonable but worth review, 3 = aggressive, 2-1 = unusual/risky.",
      "7. Categories: payment-terms, indemnity, ip, termination, mfn, audit, warranty, confidentiality, dispute-resolution, boilerplate, other.",
      "8. type: 'replace' (modify existing text), 'insert' (add new clause after the anchor paragraph), 'delete' (strike the anchor text).",
      "9. For 'insert', `insertPosition` should be 'after' (default) or 'before'.",
      "10. Do NOT propose edits that don't serve the instruction. Do NOT hallucinate clauses that aren't in the doc.",
      "11. Each edit needs a unique `id` (e1, e2, e3…).",
      "",
      "TONE: " + toneGuide,
      "",
      "INSTRUCTION:",
      active.instruction,
      "",
      "DOCUMENT (paragraph-indexed JSON — each entry: id, text, section):",
      docPayload,
    ].join("\n");
  }
  // Validate + normalize the plan returned by the AI. Drops malformed
  // edits (missing required fields) rather than failing the whole plan.
  function _validatePlan(plan) {
    if (!plan || typeof plan !== "object") {
      return { summary: "", edits: [] };
    }
    var edits = Array.isArray(plan.edits) ? plan.edits : [];
    var validated = [];
    var seenIds = {};
    edits.forEach(function (e, idx) {
      if (!e || typeof e !== "object") return;
      var id = String(e.id || ("e" + (idx + 1)));
      if (seenIds[id]) id = id + "_" + idx;
      seenIds[id] = true;
      var type = e.type === "insert" || e.type === "delete" ? e.type : "replace";
      var hasAnchor = typeof e.anchorText === "string" && e.anchorText.trim().length > 0;
      if (!hasAnchor) return; // skip malformed
      if (type !== "delete") {
        var hasReplacement = typeof e.replacementText === "string" && e.replacementText.trim().length > 0;
        if (!hasReplacement) return;
      }
      validated.push({
        id: id,
        type: type,
        paragraphId: typeof e.paragraphId === "string" ? e.paragraphId : null,
        section: typeof e.section === "string" ? e.section : null,
        anchorText: e.anchorText,
        replacementText: typeof e.replacementText === "string" ? e.replacementText : null,
        insertPosition: e.insertPosition === "before" ? "before" : "after",
        rationale: typeof e.rationale === "string" ? e.rationale : "",
        category: typeof e.category === "string" ? e.category : "other",
        confidence: Math.max(1, Math.min(5, parseInt(e.confidence, 10) || 3)),
        requiresHumanReview: !!e.requiresHumanReview,
      });
    });
    return { summary: typeof plan.summary === "string" ? plan.summary : "", edits: validated };
  }
  // Kernel completeJSON schema is a top-level shape map ({key: "type"}),
  // not full JSON Schema. We rely on the prompt to enforce the actual
  // structure, then _validatePlan does deep normalization. The schema
  // here just catches catastrophic shape failures (AI returns a string
  // instead of an object).
  var PLAN_SCHEMA = { summary: "string", edits: "object" };

  // ─── Apply ────────────────────────────────────────────────────────
  // Walks accepted edits, looks up each paragraph's bookmark range,
  // searches WITHIN that paragraph for the anchor text via host
  // helpers, then applies via insertText/insertParagraph/delete with
  // Track Changes ON. One runRaw per edit so anchoring is fresh each
  // time (Word's Track Changes layer absorbs position drift).
  function _applyAcceptedEdits() {
    if (!_egActive || !_egActive.plan) return;
    var accepted = (_egActive.plan.edits || []).filter(function (e) {
      return _egActive.acceptance[e.id] === "accepted";
    });
    if (!accepted.length) return;
    _egActive.status = "applying";
    _renderOverlayBody();
    var failures = [];
    var applied = 0;
    function _applyOne(edit) {
      return eli.host.runRaw("eli_agent:apply_one", function (context) {
        var doc = context.document;
        try { doc.changeTrackingMode = "TrackAll"; } catch (_e) {}
        // Bookmark-anchored search first (preferred — paragraph-scoped
        // via the ELI_QA_* anchors ask_eli plants on every paragraph).
        // Falls back to body-wide search if the bookmark is missing.
        if (edit.paragraphId) {
          var bm = doc.getBookmarkRangeOrNullObject(edit.paragraphId);
          bm.load("isNullObject");
          return context.sync().then(function () {
            if (bm.isNullObject) return _applyAtBodyScope(context, edit);
            return _applyInRange(context, bm, edit);
          });
        }
        return _applyAtBodyScope(context, edit);
      });
    }
    function _applyInRange(context, range, edit) {
      var helpers = (eli.host && eli.host.helpers) || {};
      var swfn = helpers.searchWithFallback;
      if (typeof swfn !== "function") {
        return Promise.reject(new Error("eli.host.helpers.searchWithFallback unavailable (host:2 required)"));
      }
      // searchWithFallback: third arg is the Word.RequestContext.
      return swfn(range, edit.anchorText, context)
        .then(function (anchorRange) {
          if (!anchorRange) throw new Error("anchor not found in paragraph");
          return _executeEdit(context, anchorRange, edit);
        });
    }
    function _applyAtBodyScope(context, edit) {
      var body = context.document.body;
      var helpers = (eli.host && eli.host.helpers) || {};
      var swfn = helpers.searchWithFallback;
      if (typeof swfn !== "function") {
        return Promise.reject(new Error("eli.host.helpers.searchWithFallback unavailable (host:2 required)"));
      }
      return swfn(body, edit.anchorText, context)
        .then(function (anchorRange) {
          if (!anchorRange) throw new Error("anchor not found in document");
          return _executeEdit(context, anchorRange, edit);
        });
    }
    function _executeEdit(context, anchorRange, edit) {
      var helpers = (eli.host && eli.host.helpers) || {};
      var amfn = helpers.applyMinimalEdit;
      if (edit.type === "delete") {
        anchorRange.delete();
        return context.sync();
      }
      if (edit.type === "insert") {
        // Insert as a new paragraph after (or before) the anchor.
        anchorRange.insertParagraph(edit.replacementText, edit.insertPosition === "before" ? "Before" : "After");
        return context.sync();
      }
      // replace — applyMinimalEdit signature: (range, original, correction, context, opts).
      if (typeof amfn === "function") {
        return amfn(anchorRange, edit.anchorText, edit.replacementText, context, { preserveFormatting: true });
      }
      anchorRange.insertText(edit.replacementText, "Replace");
      return context.sync();
    }
    function _runChain(idx) {
      if (idx >= accepted.length) {
        _egActive.applyResult = { applied: applied, failures: failures };
        _egActive.status = "applied";
        _renderOverlayBody();
        eli.log.event("tool", "eli_agent_apply_complete", {
          agent: _egActive.agent,
          applied: applied,
          failed: failures.length,
        });
        return;
      }
      var edit = accepted[idx];
      _applyOne(edit).then(function () {
        applied++;
      }, function (err) {
        failures.push({ edit: edit, reason: (err && err.message) || String(err) });
      }).then(function () {
        _runChain(idx + 1);
      });
    }
    _runChain(0);
  }

  // ─── Manage Agents modal ──────────────────────────────────────────
  // Barebones V1: list every registered agent with an enable toggle
  // and the agent's description. Tone/scope controls render but only
  // tone is editable in V1 (scope checkboxes ship in Phase 2 once the
  // planning prompt actually consumes them).
  function _openManageAgentsModal() {
    _closeManageAgentsModal();
    var modal = document.createElement("div");
    modal.id = "_eg_manage_modal";
    modal.className = "_eg_modal_backdrop";
    modal.innerHTML =
      '<div class="_eg_modal_panel">' +
        '<div class="_eg_modal_header">' +
          '<div class="_eg_modal_title">⚙ Manage Agents</div>' +
          '<button id="_eg_manage_close" type="button" class="_eg_btn_ghost">✕</button>' +
        '</div>' +
        '<div id="_eg_manage_body" class="_eg_modal_body">' +
          '<div style="font-size:11px;color:#64748b;text-align:center;padding:24px;">Loading agents…</div>' +
        '</div>' +
      '</div>';
    document.body.appendChild(modal);
    document.getElementById("_eg_manage_close").onclick = _closeManageAgentsModal;
    modal.onclick = function (ev) { if (ev.target === modal) _closeManageAgentsModal(); };
    _renderManageAgentsBody();
  }
  function _renderManageAgentsBody() {
    var body = document.getElementById("_eg_manage_body");
    if (!body) return;
    Promise.all(AGENT_REGISTRY.map(function (a) {
      return _getAgentSettings(a.id).then(function (s) { return { agent: a, settings: s }; });
    })).then(function (rows) {
      var html = '';
      rows.forEach(function (row) {
        var enabled = row.settings.enabled !== false;
        var tone = row.settings.tone || "balanced";
        html +=
          '<div class="_eg_manage_card">' +
            '<div class="_eg_manage_card_head">' +
              '<div class="_eg_manage_card_title">' +
                '<span style="font-size:18px;">' + _esc(row.agent.icon) + '</span>' +
                '<span>' + _esc(row.agent.displayName) + '</span>' +
              '</div>' +
              '<label class="_eg_toggle">' +
                '<input type="checkbox" data-eg-toggle-agent="' + _esc(row.agent.id) + '"' + (enabled ? ' checked' : '') + '>' +
                '<span>' + (enabled ? 'Enabled' : 'Disabled') + '</span>' +
              '</label>' +
            '</div>' +
            '<div class="_eg_manage_card_desc">' + _esc(row.agent.description) + '</div>' +
            '<div class="_eg_manage_card_settings">' +
              '<label class="_eg_setting_label">Default tone</label>' +
              '<select data-eg-tone="' + _esc(row.agent.id) + '">' +
                '<option value="conservative"' + (tone === "conservative" ? ' selected' : '') + '>Conservative</option>' +
                '<option value="balanced"' + (tone === "balanced" ? ' selected' : '') + '>Balanced</option>' +
                '<option value="aggressive"' + (tone === "aggressive" ? ' selected' : '') + '>Aggressive</option>' +
              '</select>' +
            '</div>' +
          '</div>';
      });
      body.innerHTML = html;
      _wireManageAgentsControls();
    }).catch(function (err) {
      body.innerHTML = '<div style="font-size:11px;color:#991b1b;padding:24px;text-align:center;">Failed to load agents: ' + _esc(err && err.message) + '</div>';
    });
  }
  function _wireManageAgentsControls() {
    document.querySelectorAll("[data-eg-toggle-agent]").forEach(function (cb) {
      cb.onchange = function () {
        var id = cb.getAttribute("data-eg-toggle-agent");
        _getAgentSettings(id).then(function (s) {
          s.enabled = cb.checked;
          return _setAgentSettings(id, s);
        }).then(function () {
          _renderManageAgentsBody();  // refresh enabled-state label
        });
      };
    });
    document.querySelectorAll("[data-eg-tone]").forEach(function (sel) {
      sel.onchange = function () {
        var id = sel.getAttribute("data-eg-tone");
        _getAgentSettings(id).then(function (s) {
          s.tone = sel.value;
          return _setAgentSettings(id, s);
        });
      };
    });
  }
  function _closeManageAgentsModal() {
    var modal = document.getElementById("_eg_manage_modal");
    if (modal && modal.parentNode) modal.parentNode.removeChild(modal);
  }

  // ─── Bus listener: paint dropdown when ask_eli mounts its input ───
  // ask_eli emits 'ask_eli:input_mounted' (additive patch) with
  // { slotEl, sendBtn, inputEl, getQaContext }. We paint into slotEl
  // and mark the send button for label-flip. If ask_eli isn't
  // patched yet (older bundle), this listener simply never fires.
  // Bundle CSS is auto-injected by the kernel from style.css — no
  // manual injection needed.
  if (eli.bus && typeof eli.bus.on === "function") {
    eli.bus.on("ask_eli:input_mounted", function (payload) {
      _paintDropdown(payload);
    });
  }

  // ─── Dispatch handlers ────────────────────────────────────────────
  // intercept_submit: ask_eli calls this BEFORE running its Q&A
  // pipeline. If the current mode isn't "ask_eli", we open the agent
  // overlay and return { handled: true } to short-circuit ask_eli's
  // Q&A path. Returning falsy lets Q&A proceed normally.
  eli.register({
    eli_agent: {
      list_agents: function () { return _listAgents(); },
      get_agent_settings: function (agentId) { return _getAgentSettings(agentId); },
      set_agent_settings: function (payload) {
        if (!payload || !payload.agentId) return Promise.reject(new Error("Missing agentId"));
        return _setAgentSettings(payload.agentId, payload.settings || {});
      },
      intercept_submit: function (payload) {
        if (!_currentMode || _currentMode === "ask_eli") return { handled: false };
        var agentId = _currentMode.replace(/^agent:/, "");
        _openAgentOverlay({
          agent: agentId,
          instruction: (payload && payload.instruction) || "",
          qaIndex: payload && payload.qaIndex,
          docHash: payload && payload.docHash,
        });
        return { handled: true };
      },
      open_agent: function (payload) { _openAgentOverlay(payload || {}); },
      get_current_mode: function () { return _currentMode; },
      set_mode: function (mode) { _setMode(mode); },
    },
    // Tile dispatch for users who pin the Manage Agents UI as a
    // standalone tile (audience controls keep this admin-only).
    tile: {
      app_eli_agent: function () { _openManageAgentsModal(); },
    },
  });

  // ─── Helpers ──────────────────────────────────────────────────────
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  eli.log.event("tool", "eli_agent_initialized", { agentCount: AGENT_REGISTRY.length });
}

jsonTools.css:
/* tools/eli_agent/style.css
   ELI Agent — dropdown trigger, menu, agent overlay, Manage Agents
   modal. Light palette throughout (per CLAUDE.md theme split rule:
   tools + dialogs use light palette in both themes). */

/* ─── Inline caret next to ask_eli title ─── */
/* Sits between "🤖 Ask ELI" text and the index status dot. No
   button chrome — just a small chevron that reads as part of the
   title text. Clicking opens the mode menu. Tints amber when an
   agent mode is active so the user can see at a glance they're
   not in default Q&A mode. */
._eg_caret_inline {
  display: inline-block;
  margin: 0 6px 0 4px;
  font-size: 11px;
  color: currentColor;
  opacity: 0.55;
  cursor: pointer;
  user-select: none;
  vertical-align: middle;
  transition: opacity 0.12s, color 0.12s, transform 0.12s;
}
._eg_caret_inline:hover {
  opacity: 1;
  transform: translateY(1px);
}
._eg_caret_inline._eg_caret_active {
  color: #f59e0b;
  opacity: 1;
}

/* ─── Dropdown menu (floating below trigger) ─── */
._eg_menu_row {
  user-select: none;
  transition: background 0.08s;
}
._eg_menu_row:hover {
  background: #f1f5f9 !important;
}
._eg_menu_row_action {
  font-style: italic;
  color: #475569 !important;
}
._eg_menu_divider {
  height: 1px;
  background: #e2e8f0;
  margin: 4px 0;
}

/* ─── Agent overlay (the panel that opens on Plan Edits) ─── */
._eg_overlay {
  position: fixed;
  top: 80px;
  right: 24px;
  width: 480px;
  height: 520px;
  min-width: 360px;
  min-height: 320px;
  z-index: 99998;
  background: #fff;
  border: 1px solid #cbd5e1;
  box-shadow: 0 16px 48px rgba(15, 23, 42, 0.32);
  font-family: Inter, 'Segoe UI', system-ui, sans-serif;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
._eg_header {
  padding: 11px 14px;
  background: linear-gradient(135deg, #1e3a8a 0%, #1565c0 100%);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  cursor: move;
  user-select: none;
  flex: 0 0 auto;
}
._eg_header_title {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}
._eg_header_icon {
  font-size: 16px;
  line-height: 1;
}
._eg_header_label {
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.02em;
}
._eg_header_actions {
  display: flex;
  gap: 4px;
}
._eg_btn_ghost {
  background: rgba(255, 255, 255, 0.18);
  border: 1px solid rgba(255, 255, 255, 0.4);
  color: #fff;
  padding: 3px 9px;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  border-radius: 0;
  line-height: 1.2;
  transition: background 0.12s;
}
._eg_btn_ghost:hover {
  background: rgba(255, 255, 255, 0.28);
}
._eg_body {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  color: #0f172a;
}
._eg_section_label {
  font: 700 9px/1.2 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: #64748b;
}
._eg_instruction {
  padding: 10px 12px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-left: 3px solid #1565c0;
  font-size: 13px;
  line-height: 1.5;
  color: #0f172a;
  white-space: pre-wrap;
}
._eg_context {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px 12px;
  background: #fff;
  border: 1px solid #e2e8f0;
  font-family: monospace;
  font-size: 11px;
  color: #475569;
}
._eg_status_box {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  background: #fef3c7;
  border: 1px solid #fcd34d;
  font-size: 11px;
  color: #92400e;
  font-weight: 600;
}
._eg_status_dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #f59e0b;
  flex-shrink: 0;
  animation: _eg_pulse 1.6s ease-in-out infinite;
}
@keyframes _eg_pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.45; }
}

/* ─── Review UI: summary, stats, edit cards, diff styling ─── */
._eg_summary {
  font-size: 12px;
  line-height: 1.55;
  color: #0f172a;
  padding: 10px 12px;
  background: #f1f5f9;
  border-left: 3px solid #1565c0;
}
._eg_review_stats {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  font-size: 10px;
}
._eg_stat {
  padding: 3px 8px;
  font-weight: 700;
  background: #fff;
  border: 1px solid #cbd5e1;
  color: #475569;
}
._eg_stat_accepted { background: #d1fae5; border-color: #6ee7b7; color: #065f46; }
._eg_stat_rejected { background: #fee2e2; border-color: #fca5a5; color: #991b1b; }
._eg_stat_pending  { background: #fef3c7; border-color: #fcd34d; color: #92400e; }

._eg_group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
._eg_group_header {
  font: 700 10px/1.2 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #1e3a8a;
  padding: 6px 0 4px;
  border-bottom: 1px solid #cbd5e1;
}
._eg_group_count {
  color: #64748b;
  font-weight: 500;
}

._eg_card {
  background: #fff;
  border: 1px solid #cbd5e1;
  border-left: 3px solid #cbd5e1;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  transition: border-color 0.12s, background 0.12s;
}
._eg_card_accepted { border-left-color: #10b981; background: #f0fdf4; }
._eg_card_rejected { border-left-color: #ef4444; background: #fef2f2; opacity: 0.6; }
._eg_card_pending  { border-left-color: #f59e0b; }
._eg_card_review   { border-left-color: #d97706; background: #fffbeb; }

._eg_card_top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
}
._eg_card_meta {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 10px;
  color: #475569;
  flex-wrap: wrap;
}
._eg_type_badge {
  font: 700 9px/1.2 monospace;
  padding: 2px 5px;
  border-radius: 2px;
  letter-spacing: 0.5px;
}
._eg_type_replace { background: #dbeafe; color: #1e3a8a; }
._eg_type_insert  { background: #d1fae5; color: #065f46; }
._eg_type_delete  { background: #fee2e2; color: #991b1b; }
._eg_card_section {
  font-weight: 600;
  color: #0f172a;
}
._eg_card_dots {
  font-family: monospace;
  font-size: 11px;
  color: #1565c0;
  letter-spacing: -1px;
}
._eg_card_review_pill {
  font: 700 9px/1.2 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  background: #fef3c7;
  color: #92400e;
  padding: 2px 6px;
  border-radius: 2px;
}

._eg_card_diff {
  font-family: Georgia, serif;
  font-size: 12px;
  line-height: 1.5;
  color: #0f172a;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
._eg_diff_orig {
  background: #fee2e2;
  padding: 6px 8px;
  border-left: 2px solid #ef4444;
}
._eg_diff_orig del {
  color: #991b1b;
  text-decoration: line-through;
}
._eg_diff_orig._eg_diff_insert_anchor {
  background: #f1f5f9;
  border-left-color: #94a3b8;
  font-size: 10px;
  font-style: italic;
  color: #475569;
  font-family: 'Inter', sans-serif;
}
._eg_diff_new {
  background: #d1fae5;
  padding: 6px 8px;
  border-left: 2px solid #10b981;
}
._eg_diff_new ins {
  color: #065f46;
  text-decoration: none;
  font-weight: 600;
}

._eg_card_rationale {
  font-size: 11px;
  color: #475569;
  font-style: italic;
  line-height: 1.4;
  padding: 4px 0 0;
  border-top: 1px dashed #e2e8f0;
}
._eg_card_actions {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}
._eg_card_btn {
  font: 600 10px/1.2 'Inter', sans-serif;
  padding: 5px 10px;
  border: 1px solid #cbd5e1;
  background: #fff;
  color: #0f172a;
  cursor: pointer;
  border-radius: 0;
  transition: background 0.1s, border-color 0.1s;
}
._eg_card_btn:hover:not(:disabled) {
  background: #f1f5f9;
  border-color: #94a3b8;
}
._eg_card_btn:disabled {
  opacity: 0.5;
  cursor: default;
}
._eg_card_accept {
  background: #ecfdf5;
  color: #065f46;
  border-color: #6ee7b7;
}
._eg_card_accept:hover:not(:disabled) { background: #d1fae5; }
._eg_card_reject {
  background: #fef2f2;
  color: #991b1b;
  border-color: #fca5a5;
}
._eg_card_reject:hover:not(:disabled) { background: #fee2e2; }
._eg_card_undo {
  background: #fff;
  color: #475569;
}

/* Sticky bottom action row in the review view. */
._eg_actions_row {
  display: flex;
  gap: 8px;
  padding: 10px 0 4px;
  flex-wrap: wrap;
  align-items: center;
}
._eg_actions_sticky {
  position: sticky;
  bottom: -16px;
  margin: 4px -16px -16px;
  padding: 12px 16px;
  background: #fff;
  border-top: 1px solid #cbd5e1;
  z-index: 5;
}
._eg_btn_primary {
  font: 700 11px/1.2 'Inter', sans-serif;
  padding: 7px 14px;
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff;
  border: 1px solid #0d47a1;
  cursor: pointer;
  border-radius: 0;
  transition: transform 0.12s, box-shadow 0.12s;
}
._eg_btn_primary:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 3px 10px rgba(21,101,192,0.28);
}
._eg_btn_primary:disabled { opacity: 0.5; cursor: default; }
._eg_btn_apply {
  margin-left: auto;
}
._eg_btn_secondary {
  font: 600 10px/1.2 'Inter', sans-serif;
  padding: 6px 12px;
  background: linear-gradient(180deg, #f8fafc 0%, #e2e8f0 100%);
  border: 1px solid #cbd5e1;
  color: #0f172a;
  cursor: pointer;
  border-radius: 0;
}
._eg_btn_secondary:hover { background: linear-gradient(180deg, #f1f5f9 0%, #cbd5e1 100%); }

/* Empty / error / applied states. */
._eg_empty_box {
  padding: 24px;
  text-align: center;
  background: #f8fafc;
  border: 1px dashed #cbd5e1;
}
._eg_empty_title {
  font-size: 13px;
  font-weight: 700;
  color: #0f172a;
  margin-bottom: 6px;
}
._eg_empty_msg {
  font-size: 11px;
  color: #64748b;
  line-height: 1.5;
}
._eg_error_box {
  padding: 14px 16px;
  background: #fef2f2;
  border: 1px solid #fca5a5;
  border-left: 3px solid #ef4444;
}
._eg_error_title {
  font-size: 12px;
  font-weight: 700;
  color: #991b1b;
  margin-bottom: 4px;
}
._eg_error_msg {
  font-size: 11px;
  color: #7f1d1d;
  line-height: 1.5;
  word-wrap: break-word;
}
._eg_applied_box {
  padding: 14px 16px;
  background: #d1fae5;
  border: 1px solid #6ee7b7;
  border-left: 3px solid #10b981;
}
._eg_applied_title {
  font-size: 13px;
  font-weight: 800;
  color: #065f46;
  margin-bottom: 4px;
}
._eg_applied_sub {
  font-size: 11px;
  color: #047857;
  line-height: 1.5;
}
._eg_fail_card {
  padding: 8px 12px;
  background: #fef2f2;
  border-left: 3px solid #ef4444;
  margin-bottom: 6px;
}
._eg_fail_reason {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: #991b1b;
  margin-bottom: 4px;
}
._eg_fail_text {
  font-size: 11px;
  color: #7f1d1d;
  font-family: Georgia, serif;
  line-height: 1.4;
  word-wrap: break-word;
}

/* ─── Manage Agents modal ─── */
._eg_modal_backdrop {
  position: fixed;
  inset: 0;
  z-index: 99999;
  background: rgba(15, 23, 42, 0.55);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: Inter, 'Segoe UI', system-ui, sans-serif;
}
._eg_modal_panel {
  background: #fff;
  width: min(640px, 92vw);
  max-height: min(720px, 88vh);
  display: flex;
  flex-direction: column;
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.4);
  border: 1px solid #cbd5e1;
  overflow: hidden;
}
._eg_modal_header {
  padding: 11px 14px;
  background: linear-gradient(135deg, #1e3a8a 0%, #1565c0 100%);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  flex: 0 0 auto;
}
._eg_modal_title {
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.02em;
}
._eg_modal_body {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  background: #f8fafc;
}
._eg_manage_card {
  background: #fff;
  border: 1px solid #cbd5e1;
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
._eg_manage_card_head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
._eg_manage_card_title {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 13px;
  font-weight: 700;
  color: #0f172a;
}
._eg_manage_card_desc {
  font-size: 11px;
  color: #475569;
  line-height: 1.5;
}
._eg_manage_card_settings {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-top: 8px;
  border-top: 1px dashed #e2e8f0;
}
._eg_setting_label {
  font: 600 10px/1.2 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: #64748b;
}
._eg_manage_card_settings select {
  padding: 5px 8px;
  font-size: 11px;
  font-family: inherit;
  border: 1px solid #cbd5e1;
  background: #fff;
  border-radius: 0;
  cursor: pointer;
  color: #0f172a;
}
._eg_toggle {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 600;
  color: #475569;
  cursor: pointer;
  user-select: none;
}
._eg_toggle input[type="checkbox"] {
  cursor: pointer;
  margin: 0;
}
